try {
    process(record);
} catch (Exception e) {
    if (retryCount.get(record.key()) < MAX_RETRIES) {
        producer.send(new ProducerRecord<>("retry-topic", record.value()));
    } else {
        producer.send(new ProducerRecord<>("dlq-topic", record.value()));
    }
    // Commit offset to move past the poison pill
    consumer.commitSync(Collections.singletonMap(topicPartition, new OffsetAndMetadata(record.offset() + 1)));
}
